{{ config(materialized='incremental', unique_key=['customer_id', 'snapshot_date'], on_schema_change='append_new_columns', incremental_strategy='delete+insert') }}
-- A cumulative table: one row per key per day, carrying its whole history. Each run computes one
-- day, run_date (dbt --vars), or the latest day with activity: yesterday's row for every key,
-- with today's activity put in front of its arrays. Rows without a key have no history to join.

with activity as (

    select
        src.customer_id as customer_id,
        cast(src.ordered_on as DATE) as activity_date,
        COUNT(*) as order_lines,
        SUM(src.net_amount) as spend
    from {{ ref('fct_order_line') }} as src
    where src.customer_id is not null
    group by src.customer_id, cast(src.ordered_on as DATE)

),

run as (

    select coalesce(
        cast(nullif('{{ var('run_date', '') }}', '') as DATE),
        (select max(activity_date) from activity)
    ) as day

),

today as (

    select activity.* from activity cross join run where activity.activity_date = run.day

),

yesterday as (
{% if is_incremental() %}
    select * from {{ this }}
    where snapshot_date = (
        select max(snapshot_date) from {{ this }} where snapshot_date < (select day from run)
    )
{% else %}
    select
        cast(null as BIGINT) as customer_id,
        cast(null as DATE[]) as dates_active,
        cast(null as BIGINT[]) as order_lines,
        cast(null as DECIMAL(18,4)[]) as spend,
        cast(null as bigint) as days_active,
        cast(null as DATE) as last_active,
        cast(null as DATE) as snapshot_date
    where 1 = 0
{% endif %}
)

select
    coalesce(t.customer_id, y.customer_id) as customer_id,
    case
        when y.dates_active is null then list_value(t.activity_date)
        when t.activity_date is null then y.dates_active
        else list_prepend(t.activity_date, y.dates_active)
    end as dates_active,
    case
        when y.order_lines is null then list_value(t.order_lines)
        when t.activity_date is null then y.order_lines
        else list_prepend(t.order_lines, y.order_lines)
    end as order_lines,
    case
        when y.spend is null then list_value(t.spend)
        when t.activity_date is null then y.spend
        else list_prepend(t.spend, y.spend)
    end as spend,
    coalesce(y.days_active, 0) + case when t.activity_date is null then 0 else 1 end as days_active,
    coalesce(t.activity_date, y.last_active) as last_active,
    run.day as snapshot_date
from today as t
full outer join yesterday as y
    on t.customer_id = y.customer_id
cross join run
